  @@ -229,8 +229,19 @@ enum SessionPTY {
  -    let targets = Set(processIDs.filter { $0 > 0 })
  -    guard !targets.isEmpty else { return [] }
  +    let roots = Set(processIDs.filter { $0 > 0 })
