/// `signalProcess: false` is for the one caller (`reapChildren`) that already knows — via a
/// `waitpid` call that JUST returned this same pid — that the process is dead. Sending it a
/// signal at that point isn't merely redundant: `waitpid` reaping a zombie releases its pid back
/// to the OS's available pool immediately, so a `killpg`/`kill` issued after that reap targets
/// WHATEVER process the OS may have already recycled that pid number to, not the session's shell.
/// Every other caller signals a process it hasn't just reaped itself, so the default stays `true`.
private func closeMaster(_ session: PTYSession, signalProcess: Bool = true) {
  guard session.masterDescriptor >= 0 else { return }
  sessionsByMaster.removeValue(forKey: session.masterDescriptor)
  SessionIO.close(session.masterDescriptor)
  session.masterDescriptor = -1
  session.isEnding = true
  if signalProcess {
    SessionPTY.terminate(processID: session.processID)
  }
}

@discardableResult
private func endSession(
  _ session: PTYSession, status: Int32, force: Bool = false, signalProcess: Bool = true
) -> Bool {
  // When `force` is set, `forceTerminate` runs right below and does its own, more thorough
  // signaling (SIGTERM/SIGKILL, verified, and aware of setsid-detached descendants via a
  // parent-pid walk) — so skip closeMaster's softer killpg(SIGHUP) here. Sending it first would
  // very likely kill the session's shell immediately (SIGHUP's default disposition is
  // terminate), which orphans any detached descendant to launchd BEFORE forceTerminate's own
  // process-tree snapshot ever runs, defeating that walk for the exact case it exists to catch.
  closeMaster(session, signalProcess: signalProcess && !force)
  guard !force || SessionPTY.forceTerminate(processID: session.processID) else {
    SessionLog.write("failed to stop session \(session.identifier.uuidString)")
    return false
  }
  finishSession(session, status: status)
  return true
}

private func endSessions(_ endingSessions: [PTYSession], status: Int32) -> Bool {
  // Always force-path semantics here (there's no non-force `killAll`) — see endSession's doc
  // comment for why closeMaster's soft signal must stay suppressed ahead of forceTerminate.

  case .resize:
    guard let identifier = connection.attachedSession,
      let session = sessions[identifier],
      let size = try? SessionResizePayload.decode(frame.payload)
    else { return }
    guard SessionWindowSizePolicy.isUsable(columns: size.columns, rows: size.rows) else { return }
    SessionPTY.resize(
      masterDescriptor: session.masterDescriptor, columns: size.columns, rows: size.rows)
  case .list:
    enqueueSessionList(sessions.values.map(\.descriptor), connection: connection)
  case .info:
    guard let identifier = try? SessionIdentifierPayload.decode(frame.payload) else { return }
    let matches = sessions[identifier].map { [$0.descriptor] } ?? []
    enqueueSessionList(matches, connection: connection)
  case .kill:
    let stopped: Bool
    if let identifier = try? SessionIdentifierPayload.decode(frame.payload),
      let session = sessions[identifier]
    {
      stopped = endSession(session, status: 0, force: true)
    } else {
      stopped = true
    }
    enqueueStopResult(stopped, connection: connection)
  case .killAll:
    enqueueStopResult(endSessions(Array(sessions.values), status: 0), connection: connection)
  case .attached, .output, .exited, .failure, .sessions, .acknowledged:
    break
  }
}

