/// `signalProcess: false` is for the one caller (`reapChildren`) that already knows — via a
/// `waitpid` call that JUST returned this same pid — that the process is dead. Sending it a
/// signal at that point isn't merely redundant: `waitpid` reaping a zombie releases its pid back
/// to the OS's available pool immediately, so a `killpg`/`kill` issued after that reap targets
/// WHATEVER process the OS may have already recycled that pid number to, not the session's shell.
/// Every other caller signals a process it hasn't just reaped itself, so the default stays `true`.
private func closeMaster(_ session: PTYSession, signalProcess: Bool = true) {
  guard session.masterDescriptor >= 0 else { return }
  sessionsByMaster.removeValue(forKey: session.masterDescriptor)
  SessionIO.close(session.masterDescriptor)
  session.masterDescriptor = -1
  session.isEnding = true
  if signalProcess {
    SessionPTY.terminate(processID: session.processID)
  }
}

@discardableResult
private func endSession(
  _ session: PTYSession, status: Int32, force: Bool = false, signalProcess: Bool = true
) -> Bool {
  // On the force path, `forceTerminate` must run against an INTACT process tree: it does its own,
  // more thorough signaling (SIGTERM/SIGKILL, verified, and aware of setsid-detached descendants
  // via a parent-pid walk), and that walk only finds a detached descendant while its parent is
  // still alive. `closeMaster` unconditionally closes the pty's master descriptor, and closing a
  // pty's last open master fd is itself a kernel-generated hangup — it sends SIGHUP to the
  // foreground process group regardless of the `signalProcess` flag (that flag only gates our own
  // EXPLICIT killpg call). Closing it before forceTerminate's snapshot would very likely kill the
  // session's shell out from under it, reparenting any detached descendant to launchd before the
  // walk ever runs. So on the force path, forceTerminate runs first and closeMaster (pure fd
  // cleanup at that point) runs after.
  guard !force else {
    SessionLog.write("DIAG endSession force pid=\(session.processID) start")
    guard SessionPTY.forceTerminate(processID: session.processID) else {
      SessionLog.write("failed to stop session \(session.identifier.uuidString)")
      return false
    }
    SessionLog.write("DIAG endSession force pid=\(session.processID) terminated")
    closeMaster(session, signalProcess: false)
    finishSession(session, status: status)
    SessionLog.write("DIAG endSession force pid=\(session.processID) finished")
    return true
  }
  closeMaster(session, signalProcess: signalProcess)
  finishSession(session, status: status)
  return true
}

private func endSessions(_ endingSessions: [PTYSession], status: Int32) -> Bool {
  // Always force-path semantics here (there's no non-force `killAll`) — see endSession's doc
  // comment for why closeMaster must not run ahead of forceTerminate's process-tree snapshot.
  let failedProcessIDs = SessionPTY.forceTerminate(processIDs: endingSessions.map(\.processID))
  for session in endingSessions { closeMaster(session, signalProcess: false) }
  for session in endingSessions where !failedProcessIDs.contains(session.processID) {
    finishSession(session, status: status)
  }
  for session in endingSessions where failedProcessIDs.contains(session.processID) {
    SessionLog.write("failed to stop session \(session.identifier.uuidString)")

